import ssb from './data/ssb-names.json';
import type { Sex } from './types';

/**
 * Names are drawn from SSB's name statistics (see scripts/fetch-names.mjs), weighted by how many
 * people in Norway have the name. Hyphenated double names (Anne-Lise, Jan-Erik) are part of the
 * SSB data; space-separated double names are generated by combining two names of the same sex.
 */

/** Share of actors given two first names (in addition to hyphenated names from SSB). */
export const DOUBLE_NAME_RATE = 0.15;

export const NAME_SOURCE = ssb.source;

class WeightedNames {
  private readonly names: string[];
  private readonly cumulative: number[];

  constructor(pairs: [string, number][]) {
    this.names = pairs.map((p) => p[0]);
    let sum = 0;
    this.cumulative = pairs.map((p) => (sum += p[1]));
  }

  get size(): number {
    return this.names.length;
  }

  pick(): string {
    const total = this.cumulative[this.cumulative.length - 1];
    const r = Math.random() * total;
    let lo = 0;
    let hi = this.cumulative.length - 1;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (this.cumulative[mid] > r) hi = mid;
      else lo = mid + 1;
    }
    return this.names[lo];
  }
}

const FEMALE = new WeightedNames(ssb.female as [string, number][]);
const MALE = new WeightedNames(ssb.male as [string, number][]);
const SURNAMES = new WeightedNames(ssb.surnames as [string, number][]);

export const givenName = (sex: Sex): string => {
  const pool = sex === 'F' ? FEMALE : MALE;
  const first = pool.pick();
  if (Math.random() >= DOUBLE_NAME_RATE || first.includes('-')) return first;
  let second = pool.pick();
  for (let i = 0; i < 10 && (second === first || second.includes('-')); i++) second = pool.pick();
  return second === first ? first : `${first} ${second}`;
};

/** Distinct surnames for new seeds, avoiding `taken`. */
export const uniqueSurnames = (count: number, taken: Iterable<string> = []): string[] => {
  const used = new Set(taken);
  const out: string[] = [];
  for (let guard = 0; out.length < count && guard < count * 200; guard++) {
    const s = SURNAMES.pick();
    if (used.has(s)) continue;
    used.add(s);
    out.push(s);
  }
  // Only reachable if nearly all SSB surnames are in use.
  for (let n = 2; out.length < count; n++) {
    const s = `${SURNAMES.pick()} ${n}`;
    if (!used.has(s)) {
      used.add(s);
      out.push(s);
    }
  }
  return out;
};

export const fullName = (a: { given: string; surname: string; id: number }): string =>
  `${a.given} ${a.surname} #${a.id}`;
